namespace Testplan {
    internal static class WebFields {
        internal static void Read(WebState state,string name,UiControl control) {
            var number=control as NumericUpDown;var check=control as CheckBox;
            state.fields[name]=number!=null?(number.Hexadecimal?((int)number.Value).ToString("X",CultureInfo.InvariantCulture):number.Value.ToString(CultureInfo.InvariantCulture)):check!=null?check.Checked.ToString().ToLowerInvariant():control.Text;
            state.enabled[name]=control.Enabled;
            var choice=control as ComboBox;if(choice!=null)state.choices[name]=choice.Items.Cast<object>().Select(x=>x.ToString()).ToArray();
        }
        internal static void Apply(Dictionary<string,string> fields,string key,UiControl control) {
            if(fields==null||!fields.ContainsKey(key))return;
            var value=fields[key]??"";if(value.Length>200000)throw new InvalidOperationException("输入内容过长。");
            var number=control as NumericUpDown;var check=control as CheckBox;var choice=control as ComboBox;
            if(!control.Enabled)return;
            if(number!=null){decimal parsed;int hex;if(number.Hexadecimal){if(!int.TryParse(value.StartsWith("0x",StringComparison.OrdinalIgnoreCase)?value.Substring(2):value,NumberStyles.HexNumber,CultureInfo.InvariantCulture,out hex))throw new InvalidOperationException(key+" 需要 HEX 值。");parsed=hex;}else if(!decimal.TryParse(value,NumberStyles.Number,CultureInfo.InvariantCulture,out parsed))throw new InvalidOperationException(key+" 需要数值。");if(parsed<number.Minimum||parsed>number.Maximum)throw new InvalidOperationException(key+" 超出原控件允许范围。");number.Value=parsed;}
            else if(check!=null){if(value!="true"&&value!="false")throw new InvalidOperationException("复选状态无效。");check.Checked=value=="true";}
            else if(choice!=null){int index=choice.FindStringExact(value);if(index<0)throw new InvalidOperationException(key+" 选项无效。");choice.SelectedIndex=index;}
            else if(control.Text!=value)control.Text=value;
        }
    }
    public partial class UART {
        internal void WebDetach(){sp.DataReceived-=sp_DataReceived;}
        internal void WebInitialize(){UART_Load(this,EventArgs.Empty);WebScan();var handle=Handle;}
        internal void WebScan(){if(sp.IsOpen)throw new InvalidOperationException("请先关闭串口再刷新端口列表。");cbxComPort.Items.Clear();cbxComPort.Items.AddRange(System.IO.Ports.SerialPort.GetPortNames().OrderBy(x=>x).ToArray());if(cbxComPort.Items.Count>0)cbxComPort.SelectedIndex=0;}
        internal void WebRead(WebState state){state.serialConnected=sp.IsOpen;state.serialState=connectionState.Text;state.serialLog=tbxRecvData.Text;WebFields.Read(state,"serial.port",cbxComPort);WebFields.Read(state,"serial.baud",cbxBaudRate);WebFields.Read(state,"serial.bits",cbxDataBits);WebFields.Read(state,"serial.stop",cbxStopBits);WebFields.Read(state,"serial.parity",cbxParity);state.fields["serial.send"]=tbxSendData.Text;state.fields["serial.hex"]=rbnSendHex.Checked.ToString().ToLowerInvariant();}
        internal void WebApply(Dictionary<string,string> fields){WebFields.Apply(fields,"serial.port",cbxComPort);WebFields.Apply(fields,"serial.baud",cbxBaudRate);WebFields.Apply(fields,"serial.bits",cbxDataBits);WebFields.Apply(fields,"serial.stop",cbxStopBits);WebFields.Apply(fields,"serial.parity",cbxParity);WebFields.Apply(fields,"serial.send",tbxSendData);if(fields!=null&&fields.ContainsKey("serial.hex")){if(fields["serial.hex"]!="true"&&fields["serial.hex"]!="false")throw new InvalidOperationException("串口显示模式无效。");rbnSendHex.Checked=fields["serial.hex"]=="true";rbnSendStr.Checked=!rbnSendHex.Checked;}}
        internal void WebAction(string operation){switch(operation){case "serial.connect":btnOpenCom_Click(btnOpenCom,EventArgs.Empty);break;case "serial.scan":WebScan();break;case "serial.send":btnSend_Click(btnSend,EventArgs.Empty);break;case "serial.clear":btnCleanData_Click(btnCleanData,EventArgs.Empty);break;default:throw new InvalidOperationException("未知串口操作。");}}
    }
    public partial class CA410 {
