        internal void WebAction(string operation){switch(operation){case "meter.connect":button1_Click(button1,EventArgs.Empty);break;case "meter.disconnect":button4_Click(button4,EventArgs.Empty);break;case "meter.measure":button2_Click(button2,EventArgs.Empty);break;default:throw new InvalidOperationException("未知仪器操作。");}}
    }
