        internal void WebRead(WebState state){state.script=richTextBox1.Text;var values=new[]{numericUpDown1,numericUpDown2,numericUpDown3,numericUpDown4,numericUpDown5,numericUpDown6};var names=new[]{"vgh","vgl","vcom","ckv","ckh","eq"};for(int i=0;i<6;i++)WebFields.Read(state,"arm."+names[i],values[i]);state.sheetColumns=dataGridView2.Columns.Cast<DataGridViewColumn>().Select(c=>c.HeaderText).ToArray();foreach(DataGridViewRow row in dataGridView2.Rows)if(!row.IsNewRow)state.sheet.Add(row.Cells.Cast<DataGridViewCell>().Select(c=>Convert.ToString(c.Value)).ToArray());}
