    public partial class Control {
        internal void WebDetach(){fs.strevent-=patterntext;}
        internal void WebInitialize(){Control_Load(this,EventArgs.Empty);var handle=Handle;}
        internal void WebRead(WebState state){state.recipe=richTextBox1.Text;state.currentLine=currentLineNum;WebFields.Read(state,"recipe.item",comboBox1);WebFields.Read(state,"recipe.preset",comboBox2);WebFields.Read(state,"recipe.start",numericUpDown1);WebFields.Read(state,"recipe.end",numericUpDown2);WebFields.Read(state,"recipe.step",numericUpDown4);WebFields.Read(state,"recipe.delay",numericUpDown3);WebFields.Read(state,"recipe.time",numericUpDown5);WebFields.Read(state,"recipe.goto",numericUpDown6);WebFields.Read(state,"recipe.pattern",textBox1);WebFields.Read(state,"recipe.download",textBox3);WebFields.Read(state,"recipe.path",textBox2);WebFields.Read(state,"recipe.downcom",checkBox1);}
        internal void WebApply(WebArguments args){var fields=args.fields;WebFields.Apply(fields,"recipe.item",comboBox1);WebFields.Apply(fields,"recipe.preset",comboBox2);WebFields.Apply(fields,"recipe.start",numericUpDown1);WebFields.Apply(fields,"recipe.end",numericUpDown2);WebFields.Apply(fields,"recipe.step",numericUpDown4);WebFields.Apply(fields,"recipe.delay",numericUpDown3);WebFields.Apply(fields,"recipe.time",numericUpDown5);WebFields.Apply(fields,"recipe.goto",numericUpDown6);WebFields.Apply(fields,"recipe.pattern",textBox1);WebFields.Apply(fields,"recipe.download",textBox3);WebFields.Apply(fields,"recipe.path",textBox2);WebFields.Apply(fields,"recipe.downcom",checkBox1);
            if(args.recipeRuns!=null){if(args.recipeRuns.Count>10000||args.recipeRuns.Sum(r=>r==null||r.text==null?0:r.text.Length)>200000)throw new InvalidOperationException("配方过长。");foreach(var run in args.recipeRuns)if(run==null||run.text==null)throw new InvalidOperationException("配方格式无效。");var text=string.Concat(args.recipeRuns.Select(r=>r.text));if(text!=richTextBox1.Text||args.recipeRuns.Any(r=>r.bold||r.italic||!string.IsNullOrEmpty(r.color))){richTextBox1.Clear();foreach(var run in args.recipeRuns){richTextBox1.SelectionFont=new Font("Consolas",10f,(run.bold?FontStyle.Bold:FontStyle.Regular)|(run.italic?FontStyle.Italic:FontStyle.Regular));Color color=Color.Black;if(!string.IsNullOrEmpty(run.color)&&System.Text.RegularExpressions.Regex.IsMatch(run.color,"^#[0-9a-fA-F]{6}$"))color=ColorTranslator.FromHtml(run.color);richTextBox1.SelectionColor=color;richTextBox1.AppendText(run.text);}}}
        }
        internal List<WebTextRun> WebRichText(){var runs=new List<WebTextRun>();int start=richTextBox1.SelectionStart,length=richTextBox1.SelectionLength;var text=richTextBox1.Text;WebTextRun last=null;int runStart=0;for(int i=0;i<text.Length;i++){richTextBox1.Select(i,1);var font=richTextBox1.SelectionFont;var selectedColor=richTextBox1.SelectionColor;var color="#"+selectedColor.R.ToString("X2")+selectedColor.G.ToString("X2")+selectedColor.B.ToString("X2");if(last==null||last.bold!=(font!=null&&font.Bold)||last.italic!=(font!=null&&font.Italic)||last.color!=color){if(last!=null)last.text=text.Substring(runStart,i-runStart);runStart=i;last=new WebTextRun{text="",bold=font!=null&&font.Bold,italic=font!=null&&font.Italic,color=color};runs.Add(last);}}if(last!=null)last.text=text.Substring(runStart);richTextBox1.Select(start,length);return runs;}
        internal void WebStop(){ns1=ns2=ns3=1;}
        internal void WebAction(string operation,WebArguments args){richTextBox1.Select(Math.Max(0,Math.Min(args.selectionStart,richTextBox1.TextLength)),Math.Max(0,Math.Min(args.selectionLength,richTextBox1.TextLength-Math.Max(0,Math.Min(args.selectionStart,richTextBox1.TextLength)))));currentLineNum=richTextBox1.GetLineFromCharIndex(richTextBox1.SelectionStart);switch(operation){case "recipe.run":WebStop();pictureBox1_Click_1(pictureBox1,EventArgs.Empty);break;case "recipe.current":WebStop();pictureBox10_Click(pictureBox10,EventArgs.Empty);break;case "recipe.step":WebStop();pictureBox4_Click(pictureBox4,EventArgs.Empty);break;case "recipe.format":pictureBox2_Click(pictureBox2,EventArgs.Empty);break;case "recipe.add":pictureBox3_Click(pictureBox3,EventArgs.Empty);break;case "recipe.up":pictureBox8_Click(pictureBox8,EventArgs.Empty);break;case "recipe.down":pictureBox9_Click(pictureBox9,EventArgs.Empty);break;case "recipe.clear":pictureBox5_Click(pictureBox5,EventArgs.Empty);break;case "recipe.import":pictureBox6_Click(pictureBox6,EventArgs.Empty);break;case "recipe.export":pictureBox7_Click(pictureBox7,EventArgs.Empty);break;case "recipe.browse":button1_Click(button1,EventArgs.Empty);break;default:throw new InvalidOperationException("未知配方操作。");}}
    }
